FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE count(*) > 100 AS chart_value GROUP BY island |> AS aggregates |> LEFT OUTER JOIN (FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE avg(body_mass_g) AS avg_body_mass_g GROUP BY island, species |> AGGREGATE bar(x => species, y => scaled(avg_body_mass_g, title => 'avg(body_mass_g)')) AS chart_bar GROUP BY island) AS charts ON aggregates.island IS NOT DISTINCT FROM charts.island |> LEFT OUTER JOIN (FROM penguins |> WHERE body_mass_g IS NOT NULL |> AGGREGATE symbol(x => bill_length_mm, y => bill_depth_mm) AS chart_symbol GROUP BY island) AS charts_2 ON aggregates.island IS NOT DISTINCT FROM charts_2.island |> SELECT aggregates.island, chart(CASE WHEN aggregates.chart_value THEN charts.chart_bar ELSE charts_2.chart_symbol END) AS chart |> ORDER BY island
